SELECT dsp.*, com.name as companyName, pro.name as productName FROM dsp_slot_info as dsp
    LEFT JOIN dsp_company as com ON dsp.company_id = com.id AND com.deleted = 0
    LEFT JOIN dsp_product as pro on dsp.product_id = pro.id AND pro.deleted = 0

    dsp.deleted = 0

        AND dsp.dsp_slot_code = #{reqVO.dspSlotCode}


        AND dsp.product_id = #{reqVO.productId}


        AND dsp.company_id = #{reqVO.companyId}


        AND dsp.name LIKE CONCAT('%', #{reqVO.name}, '%')


        AND dsp.os_type = #{reqVO.osType}


        AND dsp.dsp_pay_type = #{reqVO.dspPayType}


        AND dsp.ad_scene = #{reqVO.adScene}


        AND dsp.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}


        AND dsp.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}


ORDER BY dsp.id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM dsp_slot_info as dsp
LEFT JOIN dsp_company as com ON dsp.company_id = com.id AND com.deleted = 0
LEFT JOIN dsp_product as pro on dsp.product_id = pro.id AND pro.deleted = 0

    dsp.deleted = 0

        AND dsp.dsp_slot_code = #{reqVO.dspSlotCode}


        AND dsp.product_id = #{reqVO.productId}


        AND dsp.company_id = #{reqVO.companyId}


        AND dsp.name LIKE CONCAT('%', #{reqVO.name}, '%')


        AND dsp.os_type = #{reqVO.osType}


        AND dsp.dsp_pay_type = #{reqVO.dspPayType}


        AND dsp.ad_scene = #{reqVO.adScene}


        AND dsp.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}


        AND dsp.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}
